<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Audit,Security,Problem};
final class PersonalProblems
{
 public const FIELDS=['title'=>'عنوان مسئله','body'=>'شرح دقیق مسئله','activity'=>'زمینهٔ فعالیت','stage'=>'مرحلهٔ فعلی','attempts'=>'اقدامات قبلی','obstacles'=>'موانع اصلی','expectation'=>'انتظار از مشاوره'];
 public function __construct(private Database $db){}
 public function listing(string $uid):array {return $this->db->all('SELECT * FROM m_personal_problems WHERE user_id=? ORDER BY updated_at DESC LIMIT 50',[$uid]);}
 public function get(string $uid,string $id):array {$p=$this->db->one('SELECT * FROM m_personal_problems WHERE id=? AND user_id=?',[$id,$uid]);if(!$p)throw new Problem('NOT_FOUND','مسئلهٔ شخصی در دسترس نیست.',404);$p['terms']=array_column($this->db->all('SELECT term_id FROM m_personal_problem_terms WHERE problem_id=? ORDER BY term_id',[$id]),'term_id');$p['experiences']=array_column($this->db->all('SELECT experience_id FROM m_personal_problem_experiences WHERE problem_id=? ORDER BY experience_id',[$id]),'experience_id');return $p;}
 private function ids(mixed $value):array {if(!is_array($value)||!array_is_list($value)||count($value)>20)throw new Problem('INVALID_INPUT','حداکثر بیست مورد از فهرست انتخاب کنید.');$ids=array_values(array_unique($value));foreach($ids as $id)if(!is_string($id)||!Security::validId($id))throw new Problem('INVALID_INPUT','شناسهٔ انتخاب‌شده معتبر نیست.');sort($ids);return $ids;}
 public function normalized(string $uid,array $d):array {
  $out=[];foreach(self::FIELDS as $key=>$label){$value=$d[$key]??($key==='title'?($d['subject']??''):($key==='body'?($d['problem']??''):''));$out[$key]=Policy::text($value,$key==='title'?180:6000,$key==='title'?4:12);}
  $out['org_id']=Policy::text($d['org_id']??'',32,0)?:null;if($out['org_id']&&!(new Membership($this->db))->member($uid,$out['org_id']))throw new Problem('MEMBERSHIP_REQUIRED','برای ثبت مسئلهٔ مجموعه، عضویت تأییدشده در همان مجموعه لازم است.',403);
  $out['terms']=$this->ids($d['terms']??[]);foreach($out['terms'] as $id)if(!$this->db->one("SELECT id FROM m_terms WHERE id=? AND active=1 AND kind IN ('topic','issue')",[$id]))throw new Problem('INVALID_TOPIC','موضوع یا برچسب مسئله معتبر نیست.');
  $out['experiences']=$this->ids($d['experiences']??[]);foreach($out['experiences'] as $id)if(!$this->db->one('SELECT e.id'.AtlasData::publicBase().' WHERE e.id=?',[$id]))throw new Problem('INVALID_EXPERIENCE','تجربهٔ منتشرشده پیدا نشد.');return $out;
 }
 public function requestInput(string $uid,array $d):array {if(!empty($d['problem_id'])){$id=Policy::text($d['problem_id'],32);$p=$this->get($uid,$id);foreach(self::FIELDS as $key=>$label)$d[$key]=$p[$key];$d['terms']=$p['terms'];$d['experiences']=$p['experiences'];$d['org_id']=$p['org_id']??'';$d['subject']=$p['title'];$d['problem']=$p['body'];}$d['subject']=$d['title']??($d['subject']??'');$d['problem']=$d['body']??($d['problem']??'');return $d;}
 public function fingerprint(string $uid,array $d):string {return hash('sha256',json_encode($this->normalized($uid,$d),JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));}
 public function save(array $a,array $d):string {$uid=(new Policy($this->db))->user($a);$fn=fn()=>$this->persist($uid,$d);return $this->db->pdo->inTransaction()?$fn():(new Membership($this->db))->write($fn);}
 private function persist(string $uid,array $d):string {
  if(!$this->db->pdo->inTransaction())throw new \LogicException('Problem write needs transaction');$out=$this->normalized($uid,$d);$id=Policy::text($d['id']??$d['problem_id']??'',32,0);$hash=hash('sha256',json_encode($out,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));
  if($id){$old=$this->get($uid,$id);if(isset($d['revision'])&&(int)$d['revision']!==(int)$old['revision'])throw new Problem('REVISION_CONFLICT','مسئله تغییر کرده است؛ صفحه را تازه کنید.',409);}
  else{$existing=$this->db->one('SELECT id FROM m_personal_problems WHERE user_id=? AND content_hash=?',[$uid,$hash]);if($existing)return $existing['id'];if((int)$this->db->run('SELECT COUNT(*) FROM m_personal_problems WHERE user_id=?',[$uid])->fetchColumn()>=200)throw new Problem('LIMIT_REACHED','حداکثر دویست مسئلهٔ شخصی قابل ثبت است.');$id=Security::id();}
  $values=array_values(array_intersect_key($out,self::FIELDS));if(isset($old)){$this->db->run('UPDATE m_personal_problems SET title=?,body=?,activity=?,stage=?,attempts=?,obstacles=?,expectation=?,org_id=?,content_hash=?,revision=revision+1,updated_at=? WHERE id=? AND user_id=?',[...$values,$out['org_id'],$hash,time(),$id,$uid]);}
  else{$this->db->run('INSERT INTO m_personal_problems(id,user_id,title,body,activity,stage,attempts,obstacles,expectation,org_id,content_hash,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$uid,...$values,$out['org_id'],$hash,time(),time()]);}
  foreach(['m_personal_problem_terms','m_personal_problem_experiences'] as $table)$this->db->run('DELETE FROM '.$table.' WHERE problem_id=?',[$id]);foreach($out['terms'] as $term)$this->db->run('INSERT INTO m_personal_problem_terms VALUES(?,?)',[$id,$term]);foreach($out['experiences'] as $exp)$this->db->run('INSERT INTO m_personal_problem_experiences VALUES(?,?)',[$id,$exp]);(new Audit($this->db))->add($uid,'site','problem.saved',$id);return $id;
 }
 public function attach(array $a,array $booking,array $d):void {
  if(!(new Membership($this->db))->policy()['enabled'])return;$uid=$booking['user_id'];$hash=$this->fingerprint($uid,$d);$id=$this->persist($uid,$d);$snapshot=$this->get($uid,$id);$snapshot['_request_hash']=$hash;
  $snapshot['term_labels']=$snapshot['terms']?$this->db->all('SELECT id,kind,title FROM m_terms WHERE id IN ('.implode(',',array_fill(0,count($snapshot['terms']),'?')).')',$snapshot['terms']):[];
  $snapshot['experience_labels']=$snapshot['experiences']?$this->db->all('SELECT e.id,v.title FROM m_experiences e JOIN m_experience_versions v ON v.id=e.public_version_id WHERE e.id IN ('.implode(',',array_fill(0,count($snapshot['experiences']),'?')).')',$snapshot['experiences']):[];
  $snapshot['organization_name']=$snapshot['org_id']?($this->db->one('SELECT name FROM m_organizations WHERE id=?',[$snapshot['org_id']])['name']??''):'';
  $this->db->run("INSERT INTO m_consultation_intakes(booking_id,problem_id,snapshot_json,clarification) VALUES(?,?,?,'')",[$booking['id'],$id,json_encode($snapshot,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);
 }
 public function assertReplay(string $uid,string $bid,array $d):void {$r=$this->db->one('SELECT snapshot_json FROM m_consultation_intakes WHERE booking_id=?',[$bid]);if($r&&!hash_equals(json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR)['_request_hash'],$this->fingerprint($uid,$d)))throw new Problem('IDEMPOTENCY_CONFLICT','شناسهٔ درخواست برای شرح مسئلهٔ دیگری استفاده شده است.',409);}
 public function intake(string $bid):?array {$r=$this->db->one('SELECT * FROM m_consultation_intakes WHERE booking_id=?',[$bid]);if($r)$r['snapshot']=json_decode($r['snapshot_json'],true,512,JSON_THROW_ON_ERROR);return $r;}
 public function reply(array $a,array $d):void {
  (new Membership($this->db))->write(function()use($a,$d){$b=(new Consultations($this->db,new Audit($this->db)))->booking($a,Policy::text($d['id']??'',32));if($b['mentor_id']!==$a['user_id']||$b['state']!=='pending'||(int)$b['expires_at']<=time())throw new Problem('INVALID_STATE','درخواست قابل بررسی نیست.',409);$code=Policy::choice($d['code']??'',['clarify','unrelated','reading','capacity','refer']);$reply=$this->db->one('SELECT body FROM m_consultation_replies WHERE code=? AND active=1',[$code]);if(!$reply)throw new Problem('INVALID_INPUT','این پاسخ غیرفعال است.');$note=Policy::text($d['note']??'',2000,0);$mentor=Policy::text($d['referred_mentor']??'',32,0);if($code==='refer'){if(!$mentor||!$this->db->one("SELECT user_id FROM m_mentors WHERE user_id=? AND status='active'",[$mentor]))throw new Problem('INVALID_INPUT','مرشد پیشنهادی فعال را مشخص کنید.');}
   $intake=$this->intake($b['id']);if(!$intake)throw new Problem('INVALID_STATE','برای این درخواست قدیمی از قبول یا رد جلسه استفاده کنید.',409);$body=$reply['body'].($note!==''?' — '.$note:'');$this->db->run('UPDATE m_consultation_intakes SET needs_details=?,decision_code=?,referred_mentor_id=? WHERE booking_id=?',[(int)($code==='clarify'),$code,$code==='refer'?$mentor:null,$b['id']]);if($code!=='clarify'){$this->db->run("UPDATE m_bookings SET state='rejected' WHERE id=?",[$b['id']]);(new ConsultationCredits($this->db))->settle($b,'rejected',$a['user_id'],$body);$this->db->run("UPDATE m_time_proposals SET state='rejected' WHERE booking_id=? AND state='pending'",[$b['id']]);}
   $this->db->run('INSERT INTO m_booking_events(booking_id,actor_id,event,note,created_at) VALUES(?,?,?,?,?)',[$b['id'],$a['user_id'],$code==='clarify'?'clarification_requested':'rejected',$body,time()]);(new Audit($this->db))->add($a['user_id'],'site','booking.reply_'.$code,$b['id']);(new Audit($this->db))->notify($b['user_id'],$code==='clarify'?'درخواست توضیح تکمیلی':'پاسخ مرشد به درخواست',$body,'/booking?id='.$b['id'],'sessions');
  });
 }
 public function clarify(array $a,array $d):void {(new Membership($this->db))->write(function()use($a,$d){$b=(new Consultations($this->db,new Audit($this->db)))->booking($a,Policy::text($d['id']??'',32));$i=$this->intake($b['id']);if(!$i||!$i['needs_details']||$b['user_id']!==$a['user_id']||$b['state']!=='pending'||(int)$b['expires_at']<=time())throw new Problem('INVALID_STATE','امکان تکمیل این درخواست وجود ندارد.',409);$text=Policy::text($d['clarification']??'',6000,15);$this->db->run('UPDATE m_consultation_intakes SET needs_details=0,clarification=? WHERE booking_id=?',[$text,$b['id']]);$this->db->run('INSERT INTO m_booking_events(booking_id,actor_id,event,note,created_at) VALUES(?,?,?,?,?)',[$b['id'],$a['user_id'],'clarification_submitted',$text,time()]);(new Audit($this->db))->notify($b['mentor_id'],'توضیح تکمیلی درخواست رسید','شرح تکمیلی را در همان درخواست ببینید.','/booking?id='.$b['id'],'sessions');});}
}
